{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "You are a customer service agent that helps the user according to the <policy> provided below.",
      "requirement": "The assistant must only perform actions explicitly allowed by the policy and must not deviate from the provided instructions."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "You cannot do both [send a message to the user and make a tool call] at the same time.",
      "requirement": "The assistant must not send a message to the user simultaneously while making a tool call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "To refuel data you should: Ask them how much data they want to refuel, Confirm the price, Apply the refueled data to the line associated with the phone number the user provided.",
      "requirement": "The assistant must confirm the price of refueling with the user before applying the refueled data, unless the user explicitly agrees to the price without further confirmation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "The maximum amount of data that can be refueled is 2GB.",
      "requirement": "The amount of data refueled must not exceed 2GB per refueling request."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "You can add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The refueling must be applied at the price per GB specified by the user's current plan (P1002: $2.00 per GB)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
      "requirement": "The assistant must ensure that all feasible troubleshooting steps (e.g., confirming data refueling as a solution) are attempted before escalating to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "If `check_network_mode_preference()` shows '2G' or '3G', guide the user to use `set_network_mode_preference(mode: str)` with the mode '4g_5g_preferred' to allow the phone to connect to 5G.",
      "requirement": "If the user's network mode preference is set to '2G' or '3G' (exception: if already set to '4g_5g_preferred'), the assistant must guide the user to switch to '4g_5g_preferred' for better speed, unless the user explicitly declines or the issue is resolved by refueling."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "If the user's data usage for a line associated with the phone number the user provided exceeds the plan's data limit, data connectivity will be lost.",
      "requirement": "The assistant must ensure that the refueled data is applied to the line (L1002) where the user's data usage (15.1 GB) exceeds the plan's data limit (15.0 GB)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "The user has 2 options: Change to a plan with more data, Add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The assistant must not proceed with refueling if the user explicitly requests to change the plan, unless the user confirms the refueling option instead."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q11",
      "policy_quote": "You can add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The refueling must be applied to the line (L1002) associated with the user's phone number (555-123-2002)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "Refer to the general policy for guidelines on those options [refueling or changing plans].",
      "requirement": "The assistant must adhere to the general policy for refueling or changing plans, ensuring compliance with all specified steps and constraints."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q13",
      "policy_quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
      "requirement": "The assistant must attempt all feasible troubleshooting steps (e.g., confirming refueling as a solution) before escalating to a human agent, unless the user explicitly requests a transfer."
    }
  ]
}
